#!/usr/bin/env bash
# Refreshes the body of the release pull request vX.Y.Z (D-031) from the
# commits since the previous tag: the five sections of D-027, each entry
# linked to its commit, generated by git-cliff with .config/cliff.toml.
# Usage: bash scripts/release-pr-body.sh vX.Y.Z
set -euo pipefail

version="${1:?usage: release-pr-body.sh vX.Y.Z}"
case "$version" in
v[0-9]*.[0-9]*.[0-9]*) ;;
*)
	echo "release-pr-body: version must look like vX.Y.Z, got $version" >&2
	exit 1
	;;
esac

branch="release/$version"
# Only release tags count: a build tag such as ffmpeg-9.0.2-2 on the branch is not a release.
previous="$(git describe --tags --abbrev=0 --match 'v[0-9]*')"
count="$(git rev-list --count "$previous..HEAD")"
body="$(mktemp)"
trap 'rm -f "$body"' EXIT

{
	echo "Release pull request for **$version**: every microcommit since \`$previous\` lands on \`main\` as it is (rebase-merge, ADR-0028). After the merge, the tag \`$version\` is pushed with the author's yes."
	echo
	echo "- Commits since $previous: $count (target: about 90 per release, D-026)"
	echo "- Sections: Added, Changed (breaking change of a public interface), Removed, Fixed, Security (D-027), generated by \`git cliff --unreleased\`"
	echo
	# The first two lines of the stripped output are the [Unreleased] heading.
	git cliff --config .config/cliff.toml --unreleased --strip all | sed '1,2d'
} >"$body"

gh pr edit "$branch" --body-file "$body"
echo "release-pr-body: updated the pull request of $branch ($count commits)"
